const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase || !String(runnerBase).trim()) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const redact = (value) => {
  if (Array.isArray(value)) {
    return value.map(redact);
  }
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, entryValue]) => [
        key,
        /token|authorization|api[-_]?key|password|cookie|secret|access_token/i.test(key)
          ? '[REDACTED]'
          : redact(entryValue),
      ]),
    );
  }
  return value;
};
const sanitizedErrorPayload = redact($json);
let healthResult = null;
try {
  const healthResponse = await fetch(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'service_health_report', mode: 'sync', args: [] }),
  });
  const rawHealth = await healthResponse.text();
  healthResult = rawHealth ? JSON.parse(rawHealth) : null;
} catch (error) {
  healthResult = {
    error: error instanceof Error ? error.message : String(error),
  };
}
const reportRelativePath = `error-recovery/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Error Recovery Agent',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  '## Error Payload',
  '',
  '```json',
  JSON.stringify(sanitizedErrorPayload, null, 2),
  '```',
  '',
  '## Health Result',
  '',
  healthResult ? '```json\n' + JSON.stringify(healthResult, null, 2) + '\n```' : 'Health check unavailable.',
].join('\n');
const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
return [{ json: { reportRelativePath, healthResult } }];
